派生类模板的声明示例为：
```cpp
export template <typename T>
class GameBoard : public Grid<T> {
public:
    explicit GameBoard(
        size_t width = Grid<T>::DefaultWidth,
        size_t height = Grid<T>::DefaultHeight);
    void move(size_t xSrc, size_t ySrc,
              size_t xDest, size_t yDest);
};
```
